const DATA_CFG={source:"TD_Table_Source",mode:"TD_Mode",key:"TD_Key_Column",columns:"TD_Columns_Config",empty:"TD_NoData_Message",context:"TD_Context_Source",contextQuestion:"TD_Context_Question",hierarchy:"TD_Hierarchy_Mode",total:"TD_Show_Total",totalLabel:"TD_Total_Label",totalColumns:"TD_Total_Columns"};
function isDataTableQuestion(q){return String(questionType(q)).toLowerCase()==="tableau_donnees"}
async function ensureDataTableColumns(){const sm=S.data.QUESTIONS[0]||{},specs=[[DATA_CFG.source,"Text"],[DATA_CFG.mode,"Text"],[DATA_CFG.key,"Text"],[DATA_CFG.columns,"Text"],[DATA_CFG.empty,"Text"],[DATA_CFG.context,"Text"],[DATA_CFG.contextQuestion,"Text"],[DATA_CFG.hierarchy,"Text"],[DATA_CFG.total,"Bool"],[DATA_CFG.totalLabel,"Text"],[DATA_CFG.totalColumns,"Text"]],actions=[];for(const [id,type] of specs)if(!Object.prototype.hasOwnProperty.call(sm,id))actions.push(["AddColumn","QUESTIONS",id,{type}]);if(actions.length){await grist.docApi.applyUserActions(actions);await reload()}}
function dataColumns(q){try{return JSON.parse(q?.[DATA_CFG.columns]||"[]")}catch{return []}}
function dataTotalColumns(q){try{const v=JSON.parse(q?.[DATA_CFG.totalColumns]||"[]");return Array.isArray(v)?v:[]}catch{return []}}
function parseDataNumber(v){if(typeof v==="number")return Number.isFinite(v)?v:null;let x=String(v??"").trim().replace(/\s/g,"").replace(/€/g,"");if(!x)return null;if(x.includes(",")&&x.includes(".")){if(x.lastIndexOf(",")>x.lastIndexOf("."))x=x.replace(/\./g,"").replace(",",".");else x=x.replace(/,/g,"")}else x=x.replace(",",".");const n=Number(x);return Number.isFinite(n)?n:null}
function dataTableFields(q){const cols=dataColumns(q),mode=q?.[DATA_CFG.mode]||"all",key=q?.[DATA_CFG.key]||cols[0]?.id||"",ctx=q?.[DATA_CFG.context]||"campaign",ctxQ=q?.[DATA_CFG.contextQuestion]||"",hier=q?.[DATA_CFG.hierarchy]||"exact";const qs=(S.data.QUESTIONS||[]).filter(x=>vm(x)&&String(x.id)!==String(q.id)&&!isMatrixLine(x)&&!isDataTableQuestion(x));return `<div class="editor-section data-table-config"><h3>Tableau de données</h3><p class="field-help">Importez un fichier Excel ou CSV. La première ligne doit contenir les noms des colonnes.</p><div class="form-actions"><a class="secondary-btn" href="./modele-tableau-donnees.xlsx" download>Télécharger le modèle Excel</a><button type="button" class="btn btn-primary" id="import-data-table">Importer / remplacer les données</button><input id="data-table-file" type="file" accept=".xlsx,.csv" hidden></div><div id="data-import-info" class="hint">${q?.[DATA_CFG.source]?`Source actuelle : ${esc(q[DATA_CFG.source])}`:"Aucune donnée importée."}</div>${selectHtml("td-mode","Affichage",mode,[["all","Identique pour tous les répondants"],["personalized","Personnalisé selon le répondant"]])}<div data-td-personalized>${selectHtml("td-key","Colonne clé",key,cols.length?cols.map(c=>[c.id,c.label]):[["","Importez d’abord un fichier"]])}${selectHtml("td-context","Valeur utilisée pour filtrer",ctx,[["campaign","Structure / contexte du lien ou de la campagne"],["question","Réponse à une question"]])}<div data-td-context-question>${selectHtml("td-context-question","Question source",ctxQ,[["","Sélectionner…"],...qs.map(x=>[codeOf(x.Question_Code),label(x,"question")])])}</div>${selectHtml("td-hierarchy","Correspondance",hier,[["exact","Valeur exacte"],["value_children","Valeur + enfants directs"],["value_descendants","Valeur + tous les descendants"]])}</div>${input("td-empty","Message si aucune donnée",q?.[DATA_CFG.empty]||"Aucune donnée à afficher.")}<div class="data-columns-config"><h4>Colonnes affichées</h4>${cols.length?cols.map((c,i)=>`<div class="data-column-row"><label class="check"><input type="checkbox" name="td-col-show-${esc(c.id)}" ${c.show!==false?"checked":""}> Afficher</label><input name="td-col-label-${esc(c.id)}" value="${esc(c.label)}"><input name="td-col-order-${esc(c.id)}" type="number" value="${Number(c.order??i+1)}" min="1"></div>`).join(""):'<p class="hint">Importez un fichier pour configurer les colonnes.</p>'}</div><div class="data-total-config"><label class="check"><input type="checkbox" name="td-show-total" ${q?.[DATA_CFG.total]?"checked":""}> Afficher une ligne de total</label>${input("td-total-label","Libellé de la ligne de total",q?.[DATA_CFG.totalLabel]||"Total")}<div><div class="field-help">Colonnes à additionner</div>${cols.length?cols.map(c=>`<label class="check"><input type="checkbox" name="td-total-col-${esc(c.id)}" ${dataTotalColumns(q).includes(c.id)?"checked":""}> ${esc(c.label)}</label>`).join(""):'<span class="hint">Importez d’abord des données.</span>'}</div></div></div>`}
function cleanColumnId(name,i){let x=String(name||`Colonne_${i+1}`).normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Za-z0-9_]+/g,"_").replace(/^_+|_+$/g,"");if(!x)x=`Colonne_${i+1}`;if(/^\d/.test(x))x=`C_${x}`;return x.slice(0,60)}
async function importDataTable(q,file){await ensureDataTableColumns();const wb=await readWorkbook(file);let sheet=wb.sheets[0];if(wb.sheets.length>1){const names=wb.sheets.map((x,i)=>`${i+1}. ${x.name}`).join("\n"),ans=prompt(`Quelle feuille importer ?\n${names}`,"1");const idx=Math.max(0,Math.min(wb.sheets.length-1,Number(ans||1)-1));sheet=wb.sheets[idx]}const rows=sheet.rows.filter(r=>r.some(v=>String(v??"").trim()!==""));if(rows.length<1)throw new Error("La feuille est vide.");const headers=rows[0].map((v,i)=>String(v||`Colonne ${i+1}`).trim()||`Colonne ${i+1}`),seen=new Set(),cols=headers.map((h,i)=>{let id=cleanColumnId(h,i),base=id,n=2;while(seen.has(id))id=`${base}_${n++}`;seen.add(id);return {id,label:h,order:i+1,show:true}});const table=`GD_${cleanColumnId(codeOf(q.Question_Code)||String(q.id),0)}`.slice(0,55);try{await grist.docApi.fetchTable(table);await grist.docApi.applyUserActions([["RemoveTable",table]])}catch{}const colDefs=cols.map(c=>({id:c.id,type:"Text",isFormula:false,formula:""}));await grist.docApi.applyUserActions([["AddTable",table,colDefs]]);const actions=[];for(const row of rows.slice(1)){if(!row.some(v=>String(v??"").trim()!==""))continue;const vals={};cols.forEach((c,i)=>vals[c.id]=row[i]==null?"":String(row[i]));actions.push(["AddRecord",table,null,vals])}for(let i=0;i<actions.length;i+=200)await grist.docApi.applyUserActions(actions.slice(i,i+200));await reload();const fresh=S.data.QUESTIONS.find(x=>String(x.id)===String(q.id))||q;const ch={[DATA_CFG.source]:table,[DATA_CFG.columns]:JSON.stringify(cols),[DATA_CFG.key]:cols[0]?.id||"",[DATA_CFG.mode]:fresh[DATA_CFG.mode]||"all",[DATA_CFG.empty]:fresh[DATA_CFG.empty]||"Aucune donnée à afficher.",[DATA_CFG.context]:fresh[DATA_CFG.context]||"campaign",[DATA_CFG.hierarchy]:fresh[DATA_CFG.hierarchy]||"exact"};await grist.docApi.applyUserActions([["UpdateRecord","QUESTIONS",Number(q.id),ch]]);await reload();const updated=S.data.QUESTIONS.find(x=>String(x.id)===String(q.id));S.selected={type:"question",row:updated};renderTree();renderEditor();status(`${actions.length} ligne(s) importée(s) depuis « ${sheet.name} ».`)}
function fillDataTableChanges(q,f,ch){if(!isDataTableQuestion(q))return;ch[DATA_CFG.mode]=String(f.get("td-mode")||"all");ch[DATA_CFG.key]=String(f.get("td-key")||"");ch[DATA_CFG.empty]=String(f.get("td-empty")||"Aucune donnée à afficher.");ch[DATA_CFG.context]=String(f.get("td-context")||"campaign");ch[DATA_CFG.contextQuestion]=String(f.get("td-context-question")||"");ch[DATA_CFG.hierarchy]=String(f.get("td-hierarchy")||"exact");ch[DATA_CFG.total]=f.get("td-show-total")==="on";ch[DATA_CFG.totalLabel]=String(f.get("td-total-label")||"Total");const totalCols=dataColumns(q).filter(c=>f.get(`td-total-col-${c.id}`)==="on").map(c=>c.id);ch[DATA_CFG.totalColumns]=JSON.stringify(totalCols);const cols=dataColumns(q).map((c,i)=>({...c,show:f.get(`td-col-show-${c.id}`)==="on",label:String(f.get(`td-col-label-${c.id}`)||c.label),order:Number(f.get(`td-col-order-${c.id}`)||i+1)}));ch[DATA_CFG.columns]=JSON.stringify(cols)}

function questionFields(r){const typeKey=field(r,["Type_question","Type_reponse","Type","Format"]),req=field(r,["Mode_obligation"]),ro=field(r,["Lecture_seule"]),hidden=field(r,["Masquee"]),min=field(r,["Valeur_min"]),max=field(r,["Valeur_max"]),lmin=field(r,["Longueur_min"]),lmax=field(r,["Longueur_max"]),dec=field(r,["Nb_decimales"]),def=field(r,["Valeur_par_defaut"]),refKey=field(r,["Referentiel_Code"]);let h='<div class="editor-section"><h3>Réponse</h3>';const displayKind=displayBlockKind(r);if(!displayKind){h+=input("variable","Nom de la variable",codeOf(r.Question_Code)||"");h+='<p class="field-help">Identifiant technique utilisé dans les résultats (lettres, chiffres et _). Il doit être unique dans cette version.</p>';}
 if(typeKey){let opts=[...TYPES];const cur=String(r[typeKey]??"");if(cur&&!opts.some(x=>x[0]===cur))opts.unshift([cur,`${cur} (valeur actuelle)`]);h+=selectHtml("qtype",displayKind?"Type d’élément":"Type de question",cur,opts)}
 if(displayKind){h+=`<p class="field-help">${displayKind==="toc"?"Ce bloc affiche automatiquement le sommaire à cet emplacement. Il ne crée aucune réponse.":"Ce bloc affiche son titre et son texte à cet emplacement. Il ne crée aucune réponse."}</p></div>`;return h;}
 if(req)h+=selectHtml("required","Caractère obligatoire",r[req]??"Facultative",[["Facultative","Facultative"],["Obligatoire","Obligatoire"]]);
 if(refKey){const current=ref(r[refKey],S.data.REFERENTIELS,"Referentiel_Code");h+=`<div data-kind="choice-ref">${selectHtml("referential","Référentiel",current,[["","Aucun"],...S.data.REFERENTIELS.filter(active).map(x=>[codeOf(x.Referentiel_Code),first(x,["Nom","Libelle","Referentiel_Code"],codeOf(x.Referentiel_Code))])])}</div>`}
 h+='</div><div class="editor-section"><h3>Validation et comportement</h3>';
 if(min||max||dec)h+='<div class="two-cols" data-kind="numeric">'+(min?input("min","Valeur minimale",r[min]??"","number"):"")+(max?input("max","Valeur maximale",r[max]??"","number"):"")+(dec?input("decimals","Décimales",r[dec]??"","number"):"")+"</div>";
 if(lmin||lmax)h+='<div class="two-cols" data-kind="text-length">'+(lmin?input("lmin","Longueur minimale",r[lmin]??"","number"):"")+(lmax?input("lmax","Longueur maximale",r[lmax]??"","number"):"")+"</div>";
 if(def)h+=`<div data-kind="default">${input("default","Valeur par défaut",r[def]??"")}</div>`;
 if(ro)h+=`<label class="check"><input name="readonly" type="checkbox" ${r[ro]?"checked":""}> Lecture seule</label>`;if(hidden)h+=`<label class="check"><input name="hidden" type="checkbox" ${r[hidden]?"checked":""}> Masquée</label>`;if(field(r,["Masquer_si_choix_unique"]))h+=`<label class="check" data-kind="choice-ref"><input name="hide-single-choice" type="checkbox" ${isTrue(r.Masquer_si_choix_unique)?"checked":""}> Si un seul choix est disponible, le sélectionner automatiquement et masquer la question</label><p class="field-help" data-kind="choice-ref">S’applique aux listes déroulantes filtrées/dépendantes.</p>`;h+="</div>";
 if(isDataTableQuestion(r)){h+=dataTableFields(r);h+=conditionFields(r);return h}
 h+=conditionFields(r);
 if(isMatrixQuestion(r)){h+=matrixEditorFields(r);return h}
 const cs=choicesFor(r);h+='<div class="editor-section" data-kind="direct-choices"><h3>Choix proposés</h3><p class="field-help">Vous pouvez rendre chaque modalité disponible selon une condition ou créer automatiquement une question de précision. Enregistrez d’abord une nouvelle modalité avant de lui ajouter ces réglages.</p><div class="choice-list" id="choice-list">'+cs.map(c=>{const cc=conditionByRef(c.Condition_Code),pq=precisionQuestionFor(r,c),isMulti=isMultiChoiceType(first(r,["Type_question","Type_reponse","Type","Format"],""));return `<div class="choice-row choice-card"><div class="choice-label"><input data-choice-id="${c.id}" value="${esc(first(c,["Libelle","Libellé","Valeur"],""))}"></div><div class="choice-tools">${isMulti?`<label class="check choice-exclusive" title="Pour une question à choix multiples, cette modalité désélectionne les autres"><input type="checkbox" data-choice-exclusive="${c.id}" ${c.Exclusif?"checked":""}> Exclusif</label>`:""}<button type="button" class="secondary-btn" data-choice-condition="${c.id}" title="Condition de disponibilité">${cc?"Condition ✓":"Condition"}</button><button type="button" class="secondary-btn" data-choice-precision="${c.id}" title="Créer ou ouvrir une question de précision">${pq?"Précision ✓":"+ Précision"}</button><button type="button" class="choice-delete" data-remove-choice="${c.id}" title="Supprimer ce choix" aria-label="Supprimer ce choix">🗑</button></div></div>`}).join("")+'</div><div class="choice-actions"><button type="button" class="secondary-btn" id="add-choice">+ Ajouter un choix</button><button type="button" class="secondary-btn" id="paste-choices">Coller une liste</button></div><div id="bulk-choices" class="bulk-choices" style="display:none"><label>Un choix par ligne<textarea id="bulk-choices-text" placeholder="Choix 1&#10;Choix 2&#10;Choix 3"></textarea></label><div class="choice-actions"><button type="button" class="secondary-btn" id="import-choices">Ajouter les choix</button><button type="button" class="secondary-btn" id="cancel-bulk">Annuler</button></div></div></div>';h+=referentialPrecisionFields(r);return h}


function choiceValue(c){return String(codeOf(c?.Choix_Code)||first(c,["Valeur","Libelle","Libellé"],""))}
function precisionQuestionFor(sourceQ,choice){const expected=choiceValue(choice),isMulti=String(first(sourceQ,["Type_question","Type_reponse","Type","Format"],"")).toLowerCase().includes("case"),expectedOp=isMulti?"contient":"=";return (S.data.QUESTIONS||[]).find(q=>{const cond=conditionByRef(q.Condition_affichage_Code);if(!cond)return false;const rules=rulesForCondition(cond);return rules.length===1&&String(codeOf(rules[0].Question_source_Code))===String(sourceQ.id)&&String(rules[0].Operateur||"=")===expectedOp&&String(rules[0].Valeur_comparaison??"")===expected})||null}
function normalizeVariableName(v){return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase().replace(/[^A-Z0-9_]+/g,"_").replace(/^_+|_+$/g,"").replace(/_+/g,"_")}
function variableExists(code,exceptId=null){return (S.data.QUESTIONS||[]).some(q=>String(q.id)!==String(exceptId??"")&&vm(q)&&String(codeOf(q.Question_Code)).toUpperCase()===String(code).toUpperCase())}
function suggestPrecisionCode(q){const base=normalizeVariableName(codeOf(q.Question_Code)||"QUESTION")||"QUESTION";let code=`${base}_PRECISION`,n=2;while(variableExists(code)){code=`${base}_PRECISION_${n++}`}return code}
function precisionEditorHtml(sourceQ,choice){const existing=precisionQuestionFor(sourceQ,choice),choiceLabel=first(choice,["Libelle","Libellé","Valeur"],"cette modalité"),title=existing?label(existing,"question"):`Précisez : ${choiceLabel}`,required=existing?String(existing.Mode_obligation||"")==="Obligatoire":true;return `<div class="condition-builder" id="precision-builder"><h3>Question de précision</h3><p class="field-help">Une vraie question conditionnelle sera utilisée : elle ne s’affichera que lorsque « ${esc(choiceLabel)} » est sélectionné.</p>${input("precision-title","Libellé de la question",title)}${input("precision-variable","Nom de la variable",existing?codeOf(existing.Question_Code):suggestPrecisionCode(sourceQ))}<label class="check"><input name="precision-required" type="checkbox" ${required?"checked":""}> Réponse obligatoire lorsque la question est affichée</label><div class="form-actions">${existing?'<button type="button" class="btn btn-primary" id="open-precision">Ouvrir la question</button>':'<button type="button" class="btn btn-primary" id="create-precision">Créer la question</button>'}<button type="button" class="secondary-btn" id="cancel-precision">Annuler</button></div></div>`}
function sameRef(a,b){return String(codeOf(a)||"")===String(codeOf(b)||"")}
