function status(m,err=false,persistent=false){const node=$("#status");node.innerHTML=`<div class="${err?"status-error":"status-ok"}">${esc(m)}</div>`;if(!err&&!persistent)setTimeout(()=>{if(node.textContent===m)node.innerHTML=""},3500)}
function bind(){const inactiveToggle=$("#show-inactive");if(inactiveToggle){inactiveToggle.checked=S.showInactive;inactiveToggle.onchange=e=>{S.showInactive=Boolean(e.target.checked);renderTree()}};$("#manage-results").onclick=openResults;$("#close-results").onclick=()=>$("#results-dialog").close();$("#manage-campaigns").onclick=openCampaigns;$("#close-campaigns").onclick=()=>$("#campaigns-dialog").close();$("#manage-questionnaires").onclick=()=>{renderQuestionnaireManager();$("#manage-questionnaires-dialog").showModal()};$("#close-manage-questionnaires").onclick=()=>$("#manage-questionnaires-dialog").close();$("#respondent-preview").onclick=renderRespondentPreview;$("#close-respondent-preview").onclick=()=>$("#respondent-preview-dialog").close();$("#questionnaire-select").onchange=e=>{S.questionnaire=e.target.value;S.version=null;S.selected=null;renderSelectors();rememberRespondentPreview()};$("#version-select").onchange=e=>{S.version=e.target.value;S.selected=null;rememberRespondentPreview();renderTree()};$("#add-page").onclick=()=>add("page");$("#add-section").onclick=()=>add("section");$("#add-question").onclick=()=>add("question");$("#add-description").onclick=()=>add("description");$("#add-toc").onclick=()=>add("sommaire");$("#general-info").onclick=openGeneralInfoDialog;$("#cancel-general-info").onclick=()=>$("#general-info-dialog").close();$("#cancel-general-info-2").onclick=()=>$("#general-info-dialog").close();$("#general-info-form").elements["logo-file"].onchange=e=>{const f=e.target.files?.[0];if(f){if(f.size>750*1024){status("Le logo dépasse 750 Ko.",true,true);e.target.value="";refreshLogoPreview();return}const r=new FileReader();r.onload=()=>refreshLogoPreview(String(r.result||""));r.readAsDataURL(f)}};$("#general-info-form").elements["remove-logo"].onchange=e=>refreshLogoPreview(e.target.checked?"":currentLogo());$("#general-info-form").elements["logo-size"].onchange=()=>refreshLogoPreview($("#general-info-form").elements["remove-logo"].checked?"":($("#logo-preview").getAttribute("src")||currentLogo()));$("#general-info-form").elements["logo-align"].onchange=()=>refreshLogoPreview($("#general-info-form").elements["remove-logo"].checked?"":($("#logo-preview").getAttribute("src")||currentLogo()));$("#general-info-form").onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button[type="submit"]');btn.disabled=true;try{await saveGeneralInfo(new FormData(e.currentTarget));$("#general-info-dialog").close()}catch(err){status(`Erreur : ${err?.message||err}`,true,true)}finally{btn.disabled=false}};$("#new-questionnaire").onclick=openNewQuestionnaireDialog;$("#cancel-new-questionnaire").onclick=()=>$("#new-questionnaire-dialog").close();$("#cancel-new-questionnaire-2").onclick=()=>$("#new-questionnaire-dialog").close();$("#new-questionnaire-form").onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button[type="submit"]');btn.disabled=true;try{await createQuestionnaire(new FormData(e.currentTarget));$("#new-questionnaire-dialog").close()}catch(err){status(`Erreur : ${err?.message||err}`,true,true)}finally{btn.disabled=false}}}
async function start(){try{grist.ready({requiredAccess:"full"});await reload();bind()}catch(e){status(`Impossible de charger le Concepteur : ${e?.message||e}`,true)}}start();
